"use client"

import * as React from "react"
import { Direction, Slider as SliderPrimitive } from "radix-ui"

import { useInk, useInkSeed, useMergedRef } from "@/lib/ink/react"
import { sliderRangeRecipe, sliderThumbRecipe, sliderTrackRecipe, type SliderTone } from "@/lib/ink/recipes/slider-ink"
import { cn } from "@/lib/utils"

const THUMB = 20

function tickIntervals(ticks: boolean | number | undefined, min: number, max: number, step: number): number {
  if (!ticks) return 0
  if (typeof ticks === "number") return Math.max(0, Math.min(200, Math.round(ticks)))
  const n = Math.round((max - min) / step)
  return n >= 1 && n <= 20 ? n : 10
}

function fillWindow(from: number, to: number, thumbAtFrom: boolean, o: { vertical: boolean; startsLow: boolean }): React.CSSProperties {
  const at = (pct: number, thumb: boolean) => `calc(${thumb ? THUMB / 2 : 0}px + (100% - ${thumb ? THUMB : 0}px) * ${pct / 100})`
  const a = at(from, thumbAtFrom)
  const b = at(to, true)
  const inset = o.vertical
    ? o.startsLow
      ? `calc(100% - ${b}) -12px ${a} -12px`
      : `${a} -12px calc(100% - ${b}) -12px`
    : o.startsLow
      ? `-12px calc(100% - ${b}) -12px ${a}`
      : `-12px ${a} -12px calc(100% - ${b})`
  return { clipPath: `inset(${inset})` }
}

function SliderThumb({ seed, disabled, invalid, className, ref, ...props }: React.ComponentProps<typeof SliderPrimitive.Thumb> & { seed: string; disabled: boolean; invalid: boolean }) {
  const { hostRef, hostProps, node } = useInk({ recipe: sliderThumbRecipe, params: { disabled, invalid }, kind: "thumb", seed, still: true })
  return (
    <SliderPrimitive.Thumb
      data-slot="slider-thumb"
      ref={useMergedRef<HTMLSpanElement>(hostRef, ref)}
      {...hostProps}
      className={cn(
        "relative isolate block size-5 shrink-0 rounded-full outline-hidden transition-transform duration-(--ll-dur-press) ease-out after:absolute after:-inset-1.5 hover:scale-105 active:scale-95 disabled:pointer-events-none",
        "bg-slip data-ink-ready:bg-transparent forced-colors:rounded-full forced-colors:bg-[ButtonText]",
        className
      )}
      {...props}
    >
      {node}
    </SliderPrimitive.Thumb>
  )
}

function Slider({
  className,
  defaultValue,
  value,
  min = 0,
  max = 100,
  step = 1,
  ticks,
  tone = "marker",
  getValueText,
  seed: seedProp,
  onValueChange,
  orientation = "horizontal",
  inverted = false,
  disabled,
  dir,
  style,
  "aria-label": ariaLabel,
  "aria-labelledby": ariaLabelledby,
  "aria-describedby": ariaDescribedby,
  "aria-invalid": ariaInvalid,
  ...props
}: React.ComponentProps<typeof SliderPrimitive.Root> & {
  ticks?: boolean | number
  tone?: SliderTone
  getValueText?: (value: number, index: number) => string
  seed?: string | number
}) {
  const vertical = orientation === "vertical"
  const seed = useInkSeed(seedProp)
  const direction = Direction.useDirection(dir)
  const [uncontrolled, setUncontrolled] = React.useState<number[]>(() => (Array.isArray(defaultValue) ? defaultValue : [min]))
  const safeValue = Array.isArray(value) && value.some((v) => !Number.isFinite(v)) ? value.map((v) => (Number.isFinite(v) ? v : min)) : value
  const values = Array.isArray(safeValue) ? safeValue : uncontrolled
  const intervals = tickIntervals(ticks, min, max, step)
  const isOff = !!disabled
  const invalid = ariaInvalid === true || ariaInvalid === "true"

  const track = useInk({ recipe: sliderTrackRecipe, params: { vertical, ticks: intervals, disabled: isOff, invalid }, kind: "slider", seed: `${seed}:track`, still: true })
  const range = useInk({ recipe: sliderRangeRecipe, params: { vertical, tone, disabled: isOff }, kind: "slider", seed: `${seed}:range`, still: true })

  const span = max - min || 1
  const pct = values.map((v) => Math.min(100, Math.max(0, ((v - min) / span) * 100)))
  const multi = pct.length > 1
  const from = multi ? Math.min(...pct) : 0
  const to = pct.length ? Math.max(...pct) : 0
  const startsLow = vertical ? !inverted : (direction === "ltr") !== inverted
  const window = fillWindow(from, to, multi, { vertical, startsLow })

  return (
    <SliderPrimitive.Root
      data-slot="slider"
      defaultValue={defaultValue}
      value={safeValue}
      min={min}
      max={max}
      step={step}
      orientation={orientation}
      inverted={inverted}
      disabled={disabled}
      dir={dir}
      {...(multi ? { role: "group", "aria-label": ariaLabel, "aria-labelledby": ariaLabelledby, "aria-describedby": ariaDescribedby } : {})}
      onValueChange={(v) => {
        if (!Array.isArray(value)) setUncontrolled(v)
        onValueChange?.(v)
      }}
      style={style}
      className={cn(
        "relative flex w-full touch-none items-center select-none data-[orientation=horizontal]:min-h-6 data-[orientation=vertical]:h-full data-[orientation=vertical]:min-h-44 data-[orientation=vertical]:w-auto data-[orientation=vertical]:min-w-6 data-[orientation=vertical]:flex-col",
        className
      )}
      {...props}
    >
      <SliderPrimitive.Track
        data-slot="slider-track"
        ref={track.hostRef}
        {...track.hostProps}
        className="relative isolate grow bg-paper-shade outline-hidden data-ink-ready:bg-transparent forced-colors:border forced-colors:border-[ButtonText] data-[orientation=horizontal]:h-2 data-[orientation=horizontal]:w-full data-[orientation=vertical]:h-full data-[orientation=vertical]:w-2"
      >
        {track.node}
        <SliderPrimitive.Range
          data-slot="slider-range"
          ref={range.hostRef}
          {...range.hostProps}
          style={window}
          className="absolute isolate bg-marker/70 outline-hidden data-ink-ready:bg-transparent forced-colors:bg-[Highlight] data-[orientation=horizontal]:inset-x-0! data-[orientation=horizontal]:inset-y-0 data-[orientation=vertical]:inset-x-0 data-[orientation=vertical]:inset-y-0!"
        >
          {range.node}
        </SliderPrimitive.Range>
      </SliderPrimitive.Track>
      {values.map((_, index) => (
        <SliderThumb
          key={index}
          seed={`${seed}:thumb${index}`}
          disabled={isOff}
          invalid={invalid}
          aria-invalid={ariaInvalid}
          aria-valuetext={getValueText?.(values[index], index)}
          {...(multi ? {} : { "aria-label": ariaLabel, "aria-labelledby": ariaLabelledby, "aria-describedby": ariaDescribedby })}
        />
      ))}
    </SliderPrimitive.Root>
  )
}

export { Slider }

import { solidFill, wash } from '@/lib/ink/fills'
import { ellipsePoly, pillPoly, roundRectPoly } from '@/lib/ink/geom'
import { clamp } from '@/lib/ink/rng'
import { box, dashedBox, focusRing, loop } from '@/lib/ink/shapes'
import { defineRecipe } from '@/lib/ink/recipes'
import type { Ink } from '@/lib/ink/builder'
import type { PenName, Pt } from '@/lib/ink/types'

export const THUMB_INSET = 10

const along = (vertical: boolean, t: number, c: number): Pt => (vertical ? [c, t] : [t, c])

export interface SliderTrackParams {
  vertical?: boolean
  ticks?: number
  disabled?: boolean
  invalid?: boolean
}

export const sliderTrackRecipe = defineRecipe<SliderTrackParams>({
  id: 'slider-track',
  kind: 'slider',
  layers: ['rest'],
  pad: 12,
  draw(ink, { w, h }, { vertical = false, ticks = 0, disabled, invalid }, ctx) {
    const len = vertical ? h : w
    const th = vertical ? w : h
    const calm = ctx.calm
    const c0 = th * 0.12
    const c1 = th * 0.88
    ink.layer('rest', () => {
      const groove = vertical ? roundRectPoly(c0, 0, c1 - c0, len, 2) : roundRectPoly(0, c0, len, c1 - c0, 2)
      if (disabled) {
        wash(ink, groove, 'pencil-mark', { alpha: 0.3, material: 'wash' })
        if (vertical) dashedBox(ink, c0, 0, c1 - c0, len, { r: 2, pen: 'pencil', opts: { color: 'pencil', width: 1 } })
        else dashedBox(ink, 0, c0, len, c1 - c0, { r: 2, pen: 'pencil', opts: { color: 'pencil', width: 1 } })
      } else {
        const pill = vertical ? pillPoly(0.7, 0, th - 1.4, len) : pillPoly(0, 0.7, len, th - 1.4)
        solidFill(ink, pill, 'paper-shade', { alpha: 1, material: 'wash' })
        box(ink, vertical ? 0.7 : 0, vertical ? 0 : 0.7, vertical ? th - 1.4 : len, vertical ? len : th - 1.4, {
          pen: invalid ? (calm ? 'red.fine' : 'red') : 'ink.fine',
          corner: (th - 1.4) / 2,
          style: 'loop',
          opts: { width: 1.15, simple: len > 500 },
        })
      }
      if (ticks > 0) {
        const inset = Math.min(THUMB_INSET, len / 4)
        for (let i = 0; i <= ticks; i++) {
          const t = inset + ((len - 2 * inset) * i) / ticks
          const major = i === 0 || i === ticks
          const from = th + 2.2
          const to = from + (major ? 7.5 : 5)
          ink.stroke([along(vertical, t, from), along(vertical, t + 0.3, to)], disabled ? 'pencil' : 'ink.fine', {
            width: major ? 1.1 : 0.95, alpha: disabled ? 0.6 : 0.9, start: 'soft', end: 'flick', wobble: 0.3, simple: true,
          })
        }
      }
    })
  },
})

export const sliderToneList = ['marker', 'hi', 'blue'] as const
export type SliderTone = (typeof sliderToneList)[number]

const TONE_PEN: Record<SliderTone, PenName> = { marker: 'terracotta', hi: 'hi', blue: 'blue' }

export interface SliderRangeParams {
  vertical?: boolean
  tone?: SliderTone
  disabled?: boolean
}

export const sliderRangeRecipe = defineRecipe<SliderRangeParams>({
  id: 'slider-range',
  kind: 'slider',
  layers: ['rest'],
  pad: 12,
  draw(ink, { w, h }, { vertical = false, tone = 'marker', disabled }, ctx) {
    const len = vertical ? h : w
    const th = vertical ? w : h
    const mid = th / 2
    ink.layer('rest', () => {
      const color = disabled ? 'pencil-mark' : tone === 'hi' ? 'hi' : tone === 'blue' ? 'ink-you' : 'marker'
      const pill = vertical ? pillPoly(1.6, 0, th - 3.2, len) : pillPoly(0, 1.6, len, th - 3.2)
      solidFill(ink, pill, color, { alpha: disabled ? 0.5 : 0.96 })
    })
  },
})

export interface SliderThumbParams {
  disabled?: boolean
  invalid?: boolean
}

export const sliderThumbRecipe = defineRecipe<SliderThumbParams>({
  id: 'slider-thumb',
  kind: 'thumb',
  layers: ['rest', 'hover', 'focus'],
  lazy: ['focus'],
  pad: 12,
  draw(ink: Ink, { w, h }, { disabled, invalid }, ctx) {
    const d = Math.min(w, h)
    const cx = w / 2
    const cy = h / 2
    const R = d / 2 - 1
    const calm = ctx.calm
    if (!disabled) ctx.lazy('focus', (f) => focusRing(f, 0, 0, w, h, { shape: 'ellipse' }))
    if (ctx.lazyOnly) return
    const disc = ellipsePoly(cx, cy, R + 0.4, R + 0.4, 24)
    ink.layer('rest', () => {
      if (disabled) {
        ink.poly('under', disc, 'slip', 1)
        dashedBox(ink, 0, 0, w, h, { r: d / 2, pen: 'pencil', opts: { color: 'pencil', width: 1.1 } })
        wash(ink, ellipsePoly(cx, cy, 2.6, 2.6, 12), 'pencil-mark', { alpha: 0.6, material: 'wash' })
        return
      }
      ink.poly('under', disc, 'slip', 1)
      loop(ink, cx, cy, R, R, { pen: invalid ? (calm ? 'red.fine' : 'red') : calm ? 'pencil.fine' : 'ink', clean: true })
    })
    if (!disabled) {
      ink.layer('hover', () => {
        if (calm) {
          loop(ink, cx, cy, R - 1.6, R - 1.6, { pen: 'pencil.fine', turns: 1.05, opts: { alpha: 0.75, simple: true } })
          return
        }
        solidFill(ink, ellipsePoly(cx, cy, R - 1.2, R - 1.2, 24), 'hi', { alpha: 0.55 })
      })
    }
  },
})

